#include <iostream>
#include <string>
#include <vector>

enum class Prioridad { normal, urgente, aplazada };
struct Registro { std::string codigo; Prioridad prioridad; };
std::string nombre_prioridad(Prioridad prioridad) {
    if (prioridad == Prioridad::normal) { return "Normal"; }
    if (prioridad == Prioridad::urgente) { return "Urgent"; }
    if (prioridad == Prioridad::aplazada) { return "Deferred"; }
    return "Unrecognized";
}

int main() {
    std::vector<Registro> registros{{"R", Prioridad::urgente}, {"S", Prioridad::normal}};
    for (const auto& registro : registros) {
        std::cout << registro.codigo << ":" << nombre_prioridad(registro.prioridad) << ";";
    }
    return 0;
}
